import{_ as i,o as n,c as e,a3 as t}from"./chunks/framework.BvvarXmc.js";const d=JSON.parse('{"title":"Tata Cara Mengikuti Ujian CBT","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-siswa/mengikuti-ujian-cbt.md","filePath":"panduan-siswa/mengikuti-ujian-cbt.md","lastUpdated":null}'),l={name:"panduan-siswa/mengikuti-ujian-cbt.md"};function r(u,a,s,o,k,m){return n(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="tata-cara-mengikuti-ujian-cbt" tabindex="-1">Tata Cara Mengikuti Ujian CBT <a class="header-anchor" href="#tata-cara-mengikuti-ujian-cbt" aria-label="Permalink to &quot;Tata Cara Mengikuti Ujian CBT&quot;">​</a></h1><p>Panduan ini menjelaskan alur mengerjakan ujian online berbasis komputer / gawai dari awal hingga mengirim jawaban akhir.</p><hr><h2 id="_1-persiapan-sebelum-ujian" tabindex="-1">1. Persiapan Sebelum Ujian <a class="header-anchor" href="#_1-persiapan-sebelum-ujian" aria-label="Permalink to &quot;1. Persiapan Sebelum Ujian&quot;">​</a></h2><ul><li>Pastikan gawai (Laptop / HP) memiliki daya baterai yang cukup atau terhubung ke pengisi daya.</li><li>Pastikan koneksi internet stabil atau terhubung ke WiFi lokal sekolah yang telah ditentukan.</li><li>Tutup aplikasi lain atau tab browser yang tidak diperlukan.</li></ul><hr><h2 id="_2-memulai-ujian" tabindex="-1">2. Memulai Ujian <a class="header-anchor" href="#_2-memulai-ujian" aria-label="Permalink to &quot;2. Memulai Ujian&quot;">​</a></h2><ol><li>Masuk ke portal siswa buka menu <strong>Ujian CBT (Exams)</strong>.</li><li>Cari nama ujian yang sedang dijadwalkan (misal: <em>Penilaian Akhir Semester - Matematika</em>).</li><li>Klik tombol <strong>Mulai Ujian</strong>.</li><li>Jika ujian memerlukan <strong>Token</strong>, tanyakan kode 6 huruf/angka token kepada pengawas ujian di ruangan, lalu masukkan kode tersebut.</li><li>Bacalah petunjuk pengerjaan di layar pembuka, lalu klik <strong>Kerjakan Sekarang</strong>.</li></ol><hr><h2 id="_3-saat-mengerjakan-soal" tabindex="-1">3. Saat Mengerjakan Soal <a class="header-anchor" href="#_3-saat-mengerjakan-soal" aria-label="Permalink to &quot;3. Saat Mengerjakan Soal&quot;">​</a></h2><ul><li><strong>Waktu Tersisa</strong>: Indikator hitung mundur waktu ujian berada di bagian atas layar.</li><li><strong>Peta Navigasi Soal</strong>: Di sisi samping terdapat nomor-nomor soal: <ul><li>⬜ <strong>Putih</strong>: Belum dijawab.</li><li><strong>Hijau</strong>: Sudah dijawab.</li><li><strong>Kuning</strong>: Ragu-ragu (bisa ditandai jika ingin memeriksa ulang nanti).</li></ul></li><li><strong>Penyimpanan Otomatis (Auto-Save)</strong>: Setiap kali Anda memilih opsi jawaban, jawaban otomatis tersimpan ke server. Jika laptop tiba-tiba mati atau reload, jawaban Anda tidak akan hilang.</li></ul><hr><h2 id="_4-mengakhiri-ujian-submit" tabindex="-1">4. Mengakhiri Ujian (Submit) <a class="header-anchor" href="#_4-mengakhiri-ujian-submit" aria-label="Permalink to &quot;4. Mengakhiri Ujian (Submit)&quot;">​</a></h2><ol><li>Pada soal terakhir, pastikan seluruh nomor sudah berwarna hijau (tidak ada yang terlewat).</li><li>Klik tombol <strong>Selesai Ujian</strong>.</li><li>Sistem akan memunculkan jendela konfirmasi peringatan: <em>&quot;Apakah Anda yakin ingin mengakhiri ujian?&quot;</em>.</li><li>Centang persetujuan dan klik <strong>Ya, Kumpulkan Jawaban</strong>.</li><li>Layar akan menampilkan konfirmasi bahwa jawaban berhasil dikumpulkan.</li></ol>',14)])])}const h=i(l,[["render",r]]);export{d as __pageData,h as default};
